// lib/changedFiles.js
var processChangedFiles = async ({ filePatterns, allDiffFiles, inputs, yamlFilePatterns, workingDirectory }) => {
  if (filePatterns.length > 0) {
    startGroup("changed-files-patterns");
    const allFilteredDiffFiles = await getFilteredChangedFiles({
      allDiffFiles,
      filePatterns
    });
    debug(`All filtered diff files: ${JSON.stringify(allFilteredDiffFiles)}`);
    await setOutputsAndGetModifiedAndChangedFilesStatus({
      allDiffFiles,
      allFilteredDiffFiles,
      inputs,
      filePatterns,
      workingDirectory
    });
    info("All Done!");
    endGroup();
  }
  if (Object.keys(yamlFilePatterns).length > 0) {
    const modifiedKeys = [];
    const changedKeys = [];
    for (const key of Object.keys(yamlFilePatterns)) {
      startGroup(`changed-files-yaml-${key}`);
      const allFilteredDiffFiles = await getFilteredChangedFiles({
        allDiffFiles,
        filePatterns: yamlFilePatterns[key]
      });
      debug(`All filtered diff files for ${key}: ${JSON.stringify(allFilteredDiffFiles)}`);
      const { anyChanged, anyModified } = await setOutputsAndGetModifiedAndChangedFilesStatus({
        allDiffFiles,
        allFilteredDiffFiles,
        inputs,
        filePatterns: yamlFilePatterns[key],
        outputPrefix: key,
        workingDirectory
      });
      if (anyModified) {
        modifiedKeys.push(key);
      }
      if (anyChanged) {
        changedKeys.push(key);
      }
      info("All Done!");
      endGroup();
    }
    await setArrayOutput({
      key: "modified_keys",
      inputs,
      value: modifiedKeys
    });
    await setArrayOutput({
      key: "changed_keys",
      inputs,
      value: changedKeys
    });
  }
  if (filePatterns.length === 0 && Object.keys(yamlFilePatterns).length === 0) {
    startGroup("changed-files-all");
    await setOutputsAndGetModifiedAndChangedFilesStatus({
      allDiffFiles,
      allFilteredDiffFiles: allDiffFiles,
      inputs,
      workingDirectory
    });
    info("All Done!");
    endGroup();
  }
};
